#include <stdio.h>

enum Kind { K_INT, K_DOUBLE, K_CHAR };

typedef struct {
    enum Kind kind;
    union {
        int i;
        double d;
        char c;
    } v;
} Value;

Value make_int(int x) {
    Value r;
    r.kind = K_INT;
    r.v.i = x;
    return r;
}

Value make_double(double x) {
    Value r;
    r.kind = K_DOUBLE;
    r.v.d = x;
    return r;
}

Value make_char(char x) {
    Value r;
    r.kind = K_CHAR;
    r.v.c = x;
    return r;
}

void print_value(const Value *p) {
    switch (p->kind) {
    case K_INT:
        printf("int %d\n", p->v.i);
        break;
    case K_DOUBLE:
        printf("double %.2f\n", p->v.d);
        break;
    case K_CHAR:
        printf("char '%c'\n", p->v.c);
        break;
    default:
        printf("unknown\n");
    }
}

int main(void) {
    Value arr[6];
    int n = 0;
    for (int k = 0; k < 6; k++) {
        if (k % 3 == 0) {
            arr[n++] = make_int(k * 10);
        } else if (k % 3 == 1) {
            arr[n++] = make_double(k * 1.5);
        } else {
            arr[n++] = make_char((char)('a' + k));
        }
    }
    double total = 0.0;
    for (int k = 0; k < n; k++) {
        print_value(&arr[k]);
        switch (arr[k].kind) {
        case K_INT:
            total += arr[k].v.i;
            break;
        case K_DOUBLE:
            total += arr[k].v.d;
            break;
        case K_CHAR:
            total += 1;
            break;
        }
    }
    printf("total = %.2f\n", total);
    return 0;
}

