#include <stdio.h>

typedef union {
    int whole;
    double frac;
} Payload;

typedef enum { SHAPE_SQUARE, SHAPE_CIRCLE } ShapeKind;

typedef struct Shape {
    ShapeKind kind;
    Payload size;
} Shape;

double area(Shape s) {
    double result = 0.0;
    switch (s.kind) {
    case SHAPE_SQUARE:
        result = (double)(s.size.whole * s.size.whole);
        break;
    case SHAPE_CIRCLE:
        result = 3.14 * s.size.frac * s.size.frac;
        break;
    }
    return result;
}

void grow(Shape *p, int factor) {
    if (p->kind == SHAPE_SQUARE) {
        p->size.whole *= factor;
    } else {
        p->size.frac *= factor;
    }
}

int main(void) {
    Shape shapes[4];
    for (int i = 0; i < 4; i++) {
        if (i % 2 == 0) {
            shapes[i].kind = SHAPE_SQUARE;
            shapes[i].size.whole = i + 1;
        } else {
            shapes[i].kind = SHAPE_CIRCLE;
            shapes[i].size.frac = 0.5 * i;
        }
    }
    double sum = 0.0;
    for (int i = 0; i < 4; i++) {
        grow(&shapes[i], 2);
        double a = area(shapes[i]);
        printf("shape %d: %s area=%.2f\n", i,
               shapes[i].kind == SHAPE_SQUARE ? "square" : "circle", a);
        sum += a;
    }
    printf("sum=%.2f\n", sum);
    return 0;
}

#include <stdio.h>

typedef enum { TOK_NUM, TOK_OP, TOK_END } TokType;

typedef union TokData {
    int num;
    char op;
} TokData;

typedef struct {
    TokType type;
    TokData data;
} Token;

int apply(int acc, char op, int rhs) {
    switch (op) {
    case '+': return acc + rhs;
    case '-': return acc - rhs;
    case '*': return acc * rhs;
    case '/': return rhs != 0 ? acc / rhs : acc;
    default: return acc;
    }
}

int evaluate(const Token *toks) {
    int acc = 0;
    char pending = '+';
    for (const Token *t = toks; t->type != TOK_END; t++) {
        if (t->type == TOK_NUM) {
            acc = apply(acc, pending, t->data.num);
        } else {
            pending = t->data.op;
        }
    }
    return acc;
}

int main(void) {
    Token prog[8];
    int nums[] = {7, 3, 4, 2};
    char ops[] = {'+', '*', '-'};
    int n = 0;
    for (int i = 0; i < 4; i++) {
        prog[n].type = TOK_NUM;
        prog[n].data.num = nums[i];
        n++;
        if (i < 3) {
            prog[n].type = TOK_OP;
            prog[n].data.op = ops[i];
            n++;
        }
    }
    prog[n].type = TOK_END;
    prog[n].data.num = 0;

    for (int i = 0; prog[i].type != TOK_END; i++) {
        if (prog[i].type == TOK_NUM) {
            printf("%d ", prog[i].data.num);
        } else {
            printf("%c ", prog[i].data.op);
        }
    }
    printf("\n");
    printf("result = %d\n", evaluate(prog));
    return 0;
}

#include <stdio.h>
#include <string.h>

union Cell {
    int count;
    char name[12];
};

struct Record {
    int is_named;
    union Cell cell;
};

struct Record make_record(int k) {
    struct Record r;
    if (k % 2 == 0) {
        r.is_named = 1;
        strcpy(r.cell.name, "item");
        r.cell.name[4] = (char)('0' + k);
        r.cell.name[5] = '\0';
    } else {
        r.is_named = 0;
        r.cell.count = k * 100;
    }
    return r;
}

void describe(const struct Record *rp) {
    if (rp->is_named) {
        printf("name=%s len=%zu\n", rp->cell.name, strlen(rp->cell.name));
    } else {
        printf("count=%d\n", rp->cell.count);
    }
}

int main(void) {
    struct Record recs[5];
    union Cell *cp;
    int total = 0;
    for (int k = 0; k < 5; k++) {
        recs[k] = make_record(k);
    }
    for (int k = 0; k < 5; k++) {
        describe(&recs[k]);
        cp = &recs[k].cell;
        if (!recs[k].is_named) {
            cp->count += 1;
            total += cp->count;
        }
    }
    printf("total=%d\n", total);
    printf("sizeof(union Cell)=%zu\n", sizeof(union Cell));
    return 0;
}

#include <stdio.h>

typedef enum { OP_PUSH, OP_ADD, OP_MUL, OP_PRINT } OpCode;

typedef struct {
    OpCode code;
    union {
        int imm;
        struct {
            int times;
        } rep;
    } arg;
} Instr;

int run(Instr *prog, int len) {
    int stack[16];
    int sp = 0;
    for (int pc = 0; pc < len; pc++) {
        Instr *in = &prog[pc];
        switch (in->code) {
        case OP_PUSH:
            stack[sp++] = in->arg.imm;
            break;
        case OP_ADD: {
            int b = stack[--sp];
            int a = stack[--sp];
            stack[sp++] = a + b;
            break;
        }
        case OP_MUL: {
            int b = stack[--sp];
            int a = stack[--sp];
            stack[sp++] = a * b;
            break;
        }
        case OP_PRINT:
            for (int r = 0; r < in->arg.rep.times; r++) {
                printf("top=%d\n", stack[sp - 1]);
            }
            break;
        }
    }
    return sp > 0 ? stack[sp - 1] : -1;
}

int main(void) {
    Instr prog[7];
    prog[0].code = OP_PUSH; prog[0].arg.imm = 2;
    prog[1].code = OP_PUSH; prog[1].arg.imm = 3;
    prog[2].code = OP_ADD;  prog[2].arg.imm = 0;
    prog[3].code = OP_PUSH; prog[3].arg.imm = 4;
    prog[4].code = OP_MUL;  prog[4].arg.imm = 0;
    prog[5].code = OP_PRINT; prog[5].arg.rep.times = 2;
    prog[6].code = OP_PUSH; prog[6].arg.imm = 1;
    int last = run(prog, 7);
    printf("last=%d\n", last);
    return 0;
}

#include <iostream>
#include <iomanip>

enum class Tag { Int, Real };

union Num {
    int i;
    double d;
};

struct Entry {
    Tag tag;
    Num val;
};

Entry scale(Entry e, int k) {
    switch (e.tag) {
    case Tag::Int:
        e.val.i *= k;
        break;
    case Tag::Real:
        e.val.d *= k;
        break;
    }
    return e;
}

int main() {
    Entry list[5];
    for (int i = 0; i < 5; i++) {
        if (i < 3) {
            list[i].tag = Tag::Int;
            list[i].val.i = i + 1;
        } else {
            list[i].tag = Tag::Real;
            list[i].val.d = i * 0.25;
        }
    }
    double sum = 0;
    std::cout << std::fixed << std::setprecision(2);
    for (int i = 0; i < 5; i++) {
        Entry s = scale(list[i], 3);
        Entry *p = &s;
        if (p->tag == Tag::Int) {
            std::cout << "int " << p->val.i << "\n";
            sum += p->val.i;
        } else {
            std::cout << "real " << p->val.d << "\n";
            sum += p->val.d;
        }
    }
    std::cout << "sum " << sum << "\n";
    std::cout << "sizeof(Num) " << sizeof(Num) << "\n";
    return 0;
}

#include <iostream>
#include <string>

struct Packet {
    char kind;
    union {
        int code;
        char flag;
    };
};

int score(const Packet &p) {
    switch (p.kind) {
    case 'C':
        return p.code % 7;
    case 'F':
        return p.flag == 'y' ? 10 : 0;
    default:
        return -1;
    }
}

int main() {
    Packet ps[6];
    std::string kinds = "CFCFCX";
    for (int i = 0; i < 6; i++) {
        ps[i].kind = kinds[i];
        if (ps[i].kind == 'C') {
            ps[i].code = 13 * (i + 1);
        } else {
            ps[i].flag = (i % 3 == 0) ? 'y' : 'n';
        }
    }
    int total = 0;
    for (const Packet &p : ps) {
        int s = score(p);
        if (s < 0) {
            std::cout << "skip " << p.kind << "\n";
            continue;
        }
        total += s;
        std::cout << p.kind << " -> " << s << "\n";
    }
    std::cout << "total " << total << "\n";
    return 0;
}
